<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Dashboard</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('/dashboard',`<div class='hero'><h2>Strategic Dashboard</h2><span class='sub'>Realtime geopolitical intelligence</span></div><div id='kpi' class='grid cols-3'></div><div class='grid cols-3' style='margin-top:12px'><div class='glass-card'><h3>Top Regions</h3><div id='regions' class='list'></div></div><div class='glass-card'><h3>Top Countries</h3><div id='countries' class='list'></div></div><div class='glass-card'><h3>Top Players</h3><div id='players' class='list'></div></div></div>`);
(async()=>{try{const d=await UX.api('/api/stats/dashboard');const regs=d.top_regions||[],cts=d.top_countries||[],pls=(d.top_region_population||[]).map(x=>({id:x.id,name:'Player @'+x.name,score:x.total_population||0}));document.getElementById('kpi').innerHTML=`<div class='glass-card'><div class='sub'>Total Regions</div><div class='kpi'>${UX.fmt(regs.length)}</div></div><div class='glass-card'><div class='sub'>Total Players</div><div class='kpi'>${UX.fmt((d.top_region_population||[]).reduce((a,b)=>a+Number(b.total_population||0),0))}</div></div><div class='glass-card'><div class='sub'>Economy Score</div><div class='kpi'>${UX.fmt(cts.reduce((a,b)=>a+Number(b.total_score||0),0))}</div></div>`;regions.innerHTML=regs.slice(0,10).map((r,i)=>`<a class='row' href='/region/${r.id}'><span>${i<3?['🥇','🥈','🥉'][i]:`#${i+1}`} ${r.name}</span><b>${UX.fmt(r.score)}</b></a>`).join('');countries.innerHTML=cts.slice(0,10).map((r,i)=>`<a class='row' href='/country/${r.id}'><span>${i<3?['🥇','🥈','🥉'][i]:`#${i+1}`} ${r.country_name}</span><b>${UX.fmt(r.total_score)}</b></a>`).join('');players.innerHTML=pls.slice(0,10).map((r,i)=>`<a class='row' href='/player/${r.id}'><span>${i<3?['🥇','🥈','🥉'][i]:`#${i+1}`} ${r.name}</span><b>${UX.fmt(r.score)}</b></a>`).join('');}catch(e){pageRoot.innerHTML=`<div class='glass-card'>${e.message}</div>`;}})();
</script></body></html>
